// Experiment only: pause holds unused minutes; overlap changes require an explicit preview commit.
const seedTimeBlocks=structuredClone(blocks);
state.previewNow??=645;state.pausedWorks??=[];state.timeDraft??=null;state.timeUndo??=null;state.liveBlockId??=null;state.flowSequence??=0;
const timeId=p=>p+'-'+(++state.flowSequence)+'-'+Date.now();
function parseClock(value){let s=String(value).trim();if(/^\d{1,2}$/.test(s))s=s+':00';if(/^\d{3,4}$/.test(s))s=s.slice(0,-2)+':'+s.slice(-2);const m=/^(\d{1,2}):(\d{2})$/.exec(s);return m&&Number(m[1])<24&&Number(m[2])<60?Number(m[1])*60+Number(m[2]):null;}
const activeWork=()=>blocks.find(b=>b.id===state.liveBlockId)||blocks.find(b=>b.kind==='planned'&&minute(b.start)<=previewNow&&minute(b.end)>previewNow);
function rememberTime(label,resetClock=false){state.timeUndo={label,blocks:structuredClone(blocks),pausedWorks:structuredClone(state.pausedWorks),liveBlockId:state.liveBlockId,running:state.running,...(resetClock?{clock:previewNow}:{})};}
function reconcileLive(next){const live=blocks.find(b=>b.id===state.liveBlockId);if(!live)return;const boundary=blocks.filter(b=>b.id!==live.id&&minute(b.start)>=minute(live.start)).sort((a,b)=>a.start.localeCompare(b.start))[0],end=boundary?Math.min(next,minute(boundary.start)):next;live.end=clock(end);if(boundary&&next>=minute(boundary.start)){live.kind='recorded';state.liveBlockId=null;state.running=false;}}
function undoTime(){const u=state.timeUndo;if(!u)return;const currentLinks=new Map(blocks.map(b=>[b.id,b.noteIds]));blocks=structuredClone(u.blocks).map(b=>({...b,noteIds:currentLinks.get(b.id)||b.noteIds}));state.pausedWorks=structuredClone(u.pausedWorks);state.liveBlockId=u.liveBlockId;state.running=u.running;if(u.clock!==undefined){previewNow=u.clock;state.previewNow=previewNow;}state.timeUndo=null;state.timeDraft=null;reconcileLive(previewNow);render();persist();say('Time change undone');}
const pausedTray=document.createElement('div');pausedTray.className='flow-paused';pausedTray.dataset.pausedTray='';pausedTray.hidden=true;q('.chrome').after(pausedTray);
const timeUndoButton=document.createElement('button');timeUndoButton.type='button';timeUndoButton.dataset.flowAction='undo';timeUndoButton.textContent='Undo time change';timeUndoButton.hidden=true;q('.footer .row').appendChild(timeUndoButton);
function paintTimeControls(){const active=activeWork(),paused=state.pausedWorks[0],button=q('[data-action=timer]');button.innerHTML=icon(active?'pause':'play');button.setAttribute('aria-label',active?'Pause current work':paused?'Resume paused work':'Start timer');q('[data-timer]').textContent=active?active.home+' · '+duration(logged(active)):(paused?paused.home+' · paused':'Timer available');q('[data-preview-clock-input]').value=clock(previewNow);qa('[data-preview-clock]').forEach(b=>b.disabled=minute(b.dataset.previewClock)<previewNow);pausedTray.hidden=!state.pausedWorks.length||state.workspace!=='timesheets';pausedTray.innerHTML=state.pausedWorks.slice(0,2).map(p=>'<div class="paused-item"><span class="paused-label">'+icon('pause')+' '+esc(p.home)+' · '+p.remaining+'m remaining</span><button type="button" data-resume-work="'+p.id+'">Resume</button><button type="button" class="quiet" data-finish-work="'+p.id+'">Finish</button></div>').join('')+(state.pausedWorks.length>2?'<button type="button" data-flow-action="paused-list">'+(state.pausedWorks.length-2)+' more paused</button>':'');timeUndoButton.hidden=!state.timeUndo;icons();}
function draftValue(){const d=state.timeDraft;if(!d)return null;const start=parseClock(d.start),end=parseClock(d.end);return start!==null&&end!==null&&end>start?{start,end,home:d.home,description:d.description,kind:end>previewNow?'planned':'recorded'}:null;}
function overlapRecords(value=draftValue()){if(!value)return [];return blocks.filter(b=>b.id!==state.timeDraft?.editId&&value.start<minute(b.end)&&value.end>minute(b.start));}
function remainingPieces(b,value){const start=minute(b.start),end=minute(b.end),pieces=[];if(start<value.start)pieces.push({start:b.start,end:clock(Math.min(end,value.start))});if(end>value.end)pieces.push({start:clock(Math.max(start,value.end)),end:b.end});return pieces;}
function paintDraft(){q('[data-draft-placement]')?.remove();const value=draftValue(),track=q('.work-track');if(!value||!track)return;const range=state.range,lo=range==='afternoon'?720:480,hi=range==='day'||range==='afternoon'?1080:720;if(value.end<=lo||value.start>=hi)return;const mark=document.createElement('div');mark.className='draft-block';mark.dataset.draftPlacement='';mark.setAttribute('aria-label','Proposed '+clock(value.start)+'–'+clock(value.end));mark.style.cssText='left:'+((Math.max(value.start,lo)-lo)/(hi-lo)*100)+'%;width:calc('+((Math.min(value.end,hi)-Math.max(value.start,lo))/(hi-lo)*100)+'% - 3px);--work-color:'+workColor(value.home);mark.textContent=(value.end-value.start)+'m';track.appendChild(mark);}
function renderTimeForm(){const d=state.timeDraft;if(!d)return;q('[data-selected-entry]').innerHTML='<form class="flow-time-form" data-flow-form><header><h3>'+(d.resumeId?'Resume remaining work':d.editId?'Edit time':'Add time')+'</h3><button type="button" data-flow-action="cancel" aria-label="Cancel time entry">'+icon('x')+'</button></header>'+'<div class="flow-entry-fields"><label>Account<select data-flow-field="home"><option value="">Choose an account</option>'+accounts.map(a=>'<option '+(a===d.home?'selected':'')+'>'+a+'</option>').join('')+'</select></label><label>Description<input data-flow-field="description" value="'+esc(d.description)+'" placeholder="Press office, client call…"></label></div><div class="flow-entry-times"><label>From<input inputmode="numeric" data-flow-field="start" value="'+esc(d.start)+'" aria-label="Time entry start"></label><label>Until<input inputmode="numeric" data-flow-field="end" value="'+esc(d.end)+'" aria-label="Time entry end"></label></div>'+(!d.resumeId?'<div class="flow-durations">'+[15,25,30,60].map(m=>'<button type="button" data-duration="'+m+'">'+m+'m</button>').join('')+'</div>':'<span class="flow-entry-hint">'+d.fixedDuration+' remaining minutes · choose when to resume</span>')+'<p class="flow-error" data-flow-error role="alert" hidden></p><div class="flow-conflict" data-flow-conflict hidden></div><div class="flow-form-footer"><span class="muted" data-flow-summary></span><button type="button" data-flow-cancel data-flow-action="cancel">Cancel</button><button type="submit" class="primary" data-flow-submit>'+(d.resumeId?'Resume':d.editId?'Update':'Add time')+'</button></div></form>';updateDraftPreview();icons();}
function updateDraftPreview(){const value=draftValue(),summary=q('[data-flow-summary]');if(summary)summary.textContent=value?duration(value.end-value.start)+' · '+(value.kind==='planned'?'Work ahead':'Recorded work'):'';q('[data-flow-conflict]')?.setAttribute('hidden','');q('[data-flow-error]')?.setAttribute('hidden','');const primary=q('[data-flow-submit]'),cancel=q('[data-flow-cancel]'),d=state.timeDraft;if(primary){primary.type='submit';delete primary.dataset.flowAction;primary.textContent=d.resumeId?'Resume':d.editId?'Update':'Add time';}if(cancel){cancel.dataset.flowAction='cancel';cancel.textContent='Cancel';}paintDraft();}
function timeForm(id=null){flush();const b=blocks.find(b=>b.id===id),past=blocks.filter(b=>minute(b.end)<=previewNow).sort((a,b)=>b.end.localeCompare(a.end)),start=b?.start||past[0]?.end||clock(Math.max(0,previewNow-30)),ahead=b?minute(b.end)>previewNow:minute(start)>=previewNow;state.timeDraft={editId:id,resumeId:null,home:b?.home||'',description:b?.description||'',start,end:b?.end||clock(ahead?Math.min(1439,previewNow+30):previewNow),anchor:b||ahead?'start':'end'};state.workspace='timesheets';closeDialog(false);render();q('[data-flow-field=home]').focus();persist();}
function showConflict(value,collisions){const panel=q('[data-flow-conflict]');panel.hidden=false;panel.innerHTML='<h3>These minutes already have work</h3>'+collisions.map(b=>{const pieces=remainingPieces(b,value),overlap=Math.min(value.end,minute(b.end))-Math.max(value.start,minute(b.start));return '<div class="change-row"><span>'+esc(b.home)+' · '+esc(b.description||'Time entry')+' · '+overlap+'m overlap</span><span class="muted">'+b.start+'–'+b.end+' → '+(pieces.length?pieces.map(p=>p.start+'–'+p.end).join(' and '):'replaced in full')+'</span></div>';}).join('')+(collisions.some(b=>b.id===state.liveBlockId)?'<p class="muted">Live recording will pause when this correction is applied.</p>':'')+'';const primary=q('[data-flow-submit]'),cancel=q('[data-flow-cancel]');primary.type='button';primary.dataset.flowAction='replace';primary.textContent='Replace overlapping minutes';cancel.dataset.flowAction='keep-times';cancel.textContent='Keep existing times';icons();const area=q('[data-day]'),footer=q('.flow-form-footer'),delta=footer.getBoundingClientRect().bottom-area.getBoundingClientRect().bottom;if(delta>0)area.scrollTop+=delta+8;}
function saveTimeEntry(replace=false){const d=state.timeDraft,value=draftValue(),error=q('[data-flow-error]');if(!d)return;if(!value||!value.home){error.hidden=false;error.textContent='Choose an account and a valid start and end.';return;}if(d.resumeId&&value.end-value.start!==d.fixedDuration){error.hidden=false;error.textContent='Resume the '+d.fixedDuration+' remaining minutes. Adjust the start time to move the interval.';return;}const collisions=overlapRecords(value);if(collisions.length&&!replace){showConflict(value,collisions);return;}rememberTime(d.editId?'Edit time':d.resumeId?'Resume work':'Add time');const old=blocks.find(b=>b.id===d.editId),held=state.pausedWorks.find(p=>p.id===d.resumeId);if(replace){if(collisions.some(b=>b.id===state.liveBlockId)){state.liveBlockId=null;state.running=false;}const ids=new Set(collisions.map(b=>b.id));blocks=blocks.flatMap(b=>{if(!ids.has(b.id))return [b];return remainingPieces(b,value).map((p,i)=>({...b,...p,id:i?timeId('split'):b.id,kind:minute(p.end)>previewNow?'planned':'recorded',noteIds:[...b.noteIds]}));});}const target=old||{id:timeId('work'),noteIds:held?[...held.noteIds]:[]};Object.assign(target,{home:value.home,start:clock(value.start),end:clock(value.end),description:value.description.trim(),kind:value.kind});if(!old)blocks.push(target);if(state.liveBlockId===target.id){state.liveBlockId=null;state.running=false;}if(d.resumeId)state.pausedWorks=state.pausedWorks.filter(p=>p.id!==d.resumeId);state.timeDraft=null;state.selectedBlock=target.id;state.selectedMeeting=null;render();persist();say(replace?'Overlapping minutes reassigned · Undo available':d.resumeId?'Remaining work resumed':'Time saved');}
function pauseCurrentWork(){const b=activeWork();if(!b)return;rememberTime('Pause work');const remaining=b.kind==='planned'?Math.max(0,minute(b.end)-previewNow):0;if(remaining)state.pausedWorks.push({id:timeId('paused'),sourceId:b.id,home:b.home,description:b.description,remaining,noteIds:[...b.noteIds],originalStart:b.start,originalEnd:b.end});b.end=clock(previewNow);b.kind='recorded';if(minute(b.end)===minute(b.start))blocks=blocks.filter(x=>x.id!==b.id);state.liveBlockId=null;state.running=false;render();if(state.workspace==='timesheets'&&!state.timeDraft)q('[data-day]').scrollTop=0;persist();say(remaining?remaining+'m held for later · Undo available':'Timer paused · Undo available');}
function resumeWork(id){const p=state.pausedWorks.find(p=>p.id===id);if(!p)return;state.timeDraft={editId:null,resumeId:p.id,home:p.home,description:p.description,start:clock(previewNow),end:clock(previewNow+p.remaining),anchor:'start',fixedDuration:p.remaining};state.workspace='timesheets';closeDialog(false);render();q('[data-flow-field=start]').focus();persist();}
function beginLiveTimer(){openDialog('live-timer','Start recording','<label>Account<select data-live-home>'+accounts.map(a=>'<option>'+a+'</option>').join('')+'</select></label><div class="actions"><button type="button" data-action="close-dialog">Cancel</button><button type="button" class="primary" data-flow-action="start-live">Start timer</button></div>');}
function advanceClock(value){const next=parseClock(value);if(next===null||next<previewNow||next>1439){q('[data-clock-message]').textContent='Choose a later time, or reset the example.';q('[data-preview-clock-input]').value=clock(previewNow);return;}q('[data-clock-message]').textContent='';reconcileLive(next);previewNow=next;state.previewNow=next;render();persist();}
function resetTimeExample(){rememberTime('Reset example',true);blocks=structuredClone(seedTimeBlocks);state.pausedWorks=[];state.liveBlockId=null;state.running=false;state.timeDraft=null;state.selectedBlock=null;state.selectedMeeting=null;previewNow=645;state.previewNow=645;render();persist();say('Time example reset · notes retained');}
const originalRenderDay=renderDay;
renderDay=function(){previewNow=state.previewNow??645;root.dataset.editingTime=String(!!state.timeDraft);originalRenderDay();if(state.timeDraft)renderTimeForm();paintTimeControls();paintDraft();};
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let handled=true;
 if(b.dataset.previewClock)advanceClock(b.dataset.previewClock);
 else if(b.dataset.duration){const d=state.timeDraft,minutes=Number(b.dataset.duration),start=parseClock(d.start),end=parseClock(d.end);if(d.anchor==='end'&&end!==null)d.start=clock(Math.max(0,end-minutes));else if(start!==null)d.end=clock(Math.min(1439,start+minutes));renderTimeForm();persist();}
 else if(b.dataset.resumeWork)resumeWork(b.dataset.resumeWork);
 else if(b.dataset.finishWork){rememberTime('Finish paused work');state.pausedWorks=state.pausedWorks.filter(p=>p.id!==b.dataset.finishWork);if(dialogKind==='paused-work')closeDialog(false);render();persist();say('Unused minutes removed · Undo available');}
 else if(b.dataset.action==='timer'){if(activeWork())pauseCurrentWork();else if(state.pausedWorks.length)resumeWork(state.pausedWorks[0].id);else beginLiveTimer();}
 else if(b.dataset.flowAction==='start-live'){if(activeWork()){closeDialog();say('Pause current work before starting another timer');}else{rememberTime('Start timer');const id=timeId('live');blocks.push({id,home:q('[data-live-home]').value,start:clock(previewNow),end:clock(previewNow),description:'',kind:'live',noteIds:[]});state.liveBlockId=id;state.running=true;closeDialog();render();persist();}}
 else if(b.dataset.flowAction==='paused-list'){openDialog('paused-work','Paused work',state.pausedWorks.map(p=>'<div class="result-row"><span class="grow">'+esc(p.home)+' · '+p.remaining+'m</span><button type="button" data-resume-work="'+p.id+'">Resume</button><button type="button" data-finish-work="'+p.id+'">Finish</button></div>').join(''));}
 else if(b.dataset.flowAction==='cancel'){state.timeDraft=null;render();persist();}
 else if(b.dataset.flowAction==='keep-times'){updateDraftPreview();q('[data-flow-field=start]').focus();}
 else if(b.dataset.flowAction==='replace')saveTimeEntry(true);
 else if(b.dataset.flowAction==='undo')undoTime();
 else if(b.dataset.flowAction==='reset')resetTimeExample();
 else handled=false;
 if(handled){e.preventDefault();e.stopImmediatePropagation();}
},true);
root.addEventListener('submit',e=>{if(e.target.matches('[data-flow-form]')){e.preventDefault();saveTimeEntry();}});
root.addEventListener('input',e=>{const field=e.target.dataset.flowField,d=state.timeDraft;if(!field||!d)return;d[field]=e.target.value;if(field==='start'||field==='end'){d.anchor=field==='start'?'start':'end';const parsed=parseClock(e.target.value);if(d.resumeId&&parsed!==null){if(field==='start')d.end=clock(Math.min(1439,parsed+d.fixedDuration));else d.start=clock(Math.max(0,parsed-d.fixedDuration));const other=q('[data-flow-field='+(field==='start'?'end':'start')+']');other.value=d[field==='start'?'end':'start'];}}updateDraftPreview();persist();});
root.addEventListener('change',e=>{if(e.target.matches('[data-preview-clock-input]'))advanceClock(e.target.value);});
root.addEventListener('focusout',e=>{const field=e.target.dataset.flowField;if(!state.timeDraft||!['start','end'].includes(field))return;const parsed=parseClock(e.target.value);if(parsed!==null){state.timeDraft[field]=clock(parsed);e.target.value=clock(parsed);}});
